    -- Apply retained GameFixer patches once after SA-MP is ready.
    Optimization.applyAll()
    local serviceTick = 0

while true do
    wait(0)
    serviceTick = serviceTick + 1
    if serviceTick >= 6 then
        serviceTick = 0
        Optimization.update()
        if Environment.DistanceManager then
            Environment.DistanceManager.update()
        end
    end
		-----------------------------------------------------------------------------------
		_, id = sampGetPlayerIdByCharHandle(PLAYER_PED) --                  id
		nick = sampGetPlayerNickname(id) --               
		ping = sampGetPlayerPing(id) --                
		lvl = sampGetPlayerScore(id) --                 
		fps = ("%.0f"):format(mem.getfloat(0xB7CB50, true)) --              
		skinid = getCharModel(PLAYER_PED) --                 
        health = getCharHealth(PLAYER_PED) --             
        armour = getCharArmour(PLAYER_PED) --                  
		nowTime = os.date("%H:%M:%S", os.time())
		------------------------------------------------------------------------------------
		-- The permanent uiFrame callback owns ImGui rendering/cursor state.
        if not checkboxes.keyboard[0] then checkboxes.kbact[0] = false end if checkboxes.keyboard[0] then checkboxes.kbact[0] = true end
        timech = timech + 1
        if checkboxes.fisheye[0] then
            local desiredFov = sliders.fov[0]
            local targetFov = desiredFov

            if checkboxes.fov_aim and checkboxes.fov_aim[0] then
                local weapon = getCurrentCharWeapon(PLAYER_PED)
                if weapon and weapon > 0 and isKeyDown(2) then
                    targetFov = 70
                end
            end

            cameraSetLerpFov(targetFov, targetFov, 1000, 1)
            _OS_LAST_FOV = targetFov
        else
            _OS_LAST_FOV = nil
        end
		if checkboxes.calcbox[0] then
		    calctext = sampGetChatInputText() or ''

		    if calctext == '' then
		        calcactive = false
		        result = nil
		    else
		        local expression = calctext:gsub('%s+', '')

				local hasOperator = expression:find('[%+%-%*/%^%%]') ~= nil

				-- Разрешённые символы
				if not expression:match('^[%d%.%+%-%*/%^%%%(%)]+$') or not hasOperator then
				    calcactive = false
				    result = nil
				else
		            local pos = 1
		            local len = #expression

		            local parseExpression
		            local parseAddSub
		            local parseMulDiv
		            local parsePower
		            local parseUnary
		            local parsePrimary

		            ----------------------------------------------------------------
		            -- PRIMARY
		            -- Числа и скобки
		            ----------------------------------------------------------------

		            parsePrimary = function()
		                local start = pos

		                -- Число
		                while pos <= len and expression:sub(pos, pos):match('[%d%.]') do
		                    pos = pos + 1
		                end

		                if pos > start then
		                    local value = tonumber(expression:sub(start, pos - 1))

		                    if not value then
		                        error('invalid number')
		                    end

		                    -- Постфиксный %
		                    if expression:sub(pos, pos) == '%' then
		                        pos = pos + 1
		                        return {
		                            value = value,
		                            percent = true
		                        }
		                    end

		                    return {
		                        value = value,
		                        percent = false
		                    }
		                end

		                -- Скобки
		                if expression:sub(pos, pos) == '(' then
		                    pos = pos + 1

		                    local value = parseExpression()

		                    if expression:sub(pos, pos) ~= ')' then
		                        error('missing )')
		                    end

		                    pos = pos + 1

		                    -- (50+50)%
		                    if expression:sub(pos, pos) == '%' then
		                        pos = pos + 1
		                        value.value = value.value / 100
		                        value.percent = true
		                    end

		                    return value
		                end

		                error('unexpected character')
		            end

		            ----------------------------------------------------------------
		            -- UNARY
		            ----------------------------------------------------------------

		            parseUnary = function()
		                local char = expression:sub(pos, pos)

		                if char == '+' then
		                    pos = pos + 1
		                    return parseUnary()
		                end

		                if char == '-' then
		                    pos = pos + 1
		                    local value = parseUnary()
		                    value.value = -value.value
		                    return value
		                end

		                return parsePrimary()
		            end

		            ----------------------------------------------------------------
		            -- POWER
		            ----------------------------------------------------------------

		            parsePower = function()
		                local left = parseUnary()

		                while expression:sub(pos, pos) == '^' do
		                    pos = pos + 1

		                    local right = parseUnary()

		                    left.value = left.value ^ right.value
		                    left.percent = false
		                end

		                return left
		            end

		            ----------------------------------------------------------------
		            -- УМНОЖЕНИЕ / ДЕЛЕНИЕ
		            --
		            -- 500*20% = 100
		            -- 500/20% = 2500
		            ----------------------------------------------------------------

		            parseMulDiv = function()
		                local left = parsePower()

		                while true do
		                    local op = expression:sub(pos, pos)

		                    if op ~= '*' and op ~= '/' then
		                        break
		                    end

		                    pos = pos + 1

		                    local right = parsePower()

		                    local rightValue = right.value

		                    -- Для * и / процент означает число / 100
		                    if right.percent then
		                        rightValue = rightValue / 100
		                    end

		                    if op == '*' then
		                        left.value = left.value * rightValue
		                    else
		                        if rightValue == 0 then
		                            error('division by zero')
		                        end

		                        left.value = left.value / rightValue
		                    end

		                    left.percent = false
		                end

		                return left
		            end

		            ----------------------------------------------------------------
		            -- СЛОЖЕНИЕ / ВЫЧИТАНИЕ
		            --
		            -- 500+20% = 600
		            -- 500-20% = 400
		            ----------------------------------------------------------------

		            parseAddSub = function()
		                local left = parseMulDiv()

		                while true do
		                    local op = expression:sub(pos, pos)

		                    if op ~= '+' and op ~= '-' then
		                        break
		                    end

		                    pos = pos + 1

		                    local right = parseMulDiv()

		                    local rightValue = right.value

		                    -- Если справа процент:
		                    -- 500 + 20% = 500 + (500 * 20 / 100)
		                    -- 500 - 20% = 500 - (500 * 20 / 100)
		                    if right.percent then
		                        rightValue = left.value * rightValue / 100
		                    end

		                    if op == '+' then
		                        left.value = left.value + rightValue
		                    else
		                        left.value = left.value - rightValue
		                    end

		                    left.percent = false
		                end

		                return left
		            end

		            ----------------------------------------------------------------
		            -- ОБЩЕЕ ВЫРАЖЕНИЕ
		            ----------------------------------------------------------------

		            parseExpression = function()
		                return parseAddSub()
		            end

		            ----------------------------------------------------------------
		            -- ЗАПУСК
		            ----------------------------------------------------------------

		            local ok, parsed = pcall(function()
		                local value = parseExpression()

		                -- После выражения ничего не должно остаться
		                if pos <= len then
		                    error('unexpected characters')
		                end

		                return value
		            end)

		            if ok and parsed and type(parsed.value) == 'number'
		                and parsed.value == parsed.value
		                and parsed.value ~= math.huge
		                and parsed.value ~= -math.huge then

		                calcactive = true
		                result = tostring(parsed.value)
		            else
		                calcactive = false
		                result = nil
		            end
		        end
		    end
		end
        if (isKeyDown(VK_T) and wasKeyPressed(VK_T))then
			if(not sampIsChatInputActive() and not sampIsDialogActive())then
				sampSetChatInputEnabled(true)
			end
		end
   --     Config.save(cfg)
        if cfg.settings.cheatcode == '' then cfg.settings.cheatcode = 'oh' buffers.cheatcode = FfiBuffer(tostring(cfg.settings.cheatcode), 64) end
    	if ints.active[0] == 1 and testCheat(cfg.settings.cheatcode) then setMainWindowVisible(not frames.window[0]) end
		if checkboxes.drift[0] then
			if isCharInAnyCar(playerPed) then 
				local car = storeCarCharIsInNoSave(playerPed)
				local speed = getCarSpeed(car)
				isCarInAirProper(car)
				setCarCollision(car, true)
					if isKeyDown(VK_LSHIFT) and isVehicleOnAllWheels(car) and doesVehicleExist(car) and speed > 5.0 then
					setCarCollision(car, false)
						if isCarInAirProper(car) then setCarCollision(car, true)
						if isKeyDown(VK_A)
						then 
						addToCarRotationVelocity(car, 0, 0, 0.15)
						end
						if isKeyDown(VK_D)
						then 			
						addToCarRotationVelocity(car, 0, 0, -0.15)	
						end
					end
				end
			end
		end
		if checkboxes.infrun[0] then mem.setint8(0xB7CEE4, 1) end
    -- hotkeys
        processCustomBinds()
        if not sampIsCursorActive() then
            if checkboxes.balloon[0] and customBindDown(cfg.binds.balloon) then
                setVirtualKeyDown(1, true)
                wait(ints.autoclickerDelay[0])
                setVirtualKeyDown(1, false)
            end
            -- +W moto/bike is handled by a separate thread.
            -- Do not block the main loop with wait(50) here.	
			if ztimer == 0 then
				ztimer = ztimer - 1
				msg('Метка особо опасного преступника слетела, можете безопасно выходить из игры.')
				wait(1000)
			end
		end
	end -- cancel
end

function autoRunLoop()
    while true do
        if checkboxes.autorun[0] and isCharOnFoot(playerPed) and customBindDown(cfg.binds.autorun) then 
            wait(10)				
            setGameKeyState(16, 0)
        end
        wait(0)
    end
end
